#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t; cin >> t;
    while(t--) {
        int n,k; cin >> n >> k;
        string s; 
        cin >> s;
        int mxi=-1;
        int count=0;
        for(int i=0;i<n;i++) {
            if(s[i]=='G') count++;
            if(count==k+2) {
                mxi=i;
                break;
            }
        }
        if(mxi==-1) {
            cout << "YES" << endl;
            continue;
        }
        int cost=0;
        for(int i=mxi+1;i<n;i++) {
            if(s[i]=='G') cost+=1;
            else cost+=2;
        }
        if(cost>k) cout << "NO" << endl;
        else cout << "YES" << endl;
    }
}
